std::vector<int> data = {10, 20, 30, 40};
std::ostream& os = std::cout;

// 1. Definition: Type <T>, Stream Char Type, optional delimiter
std::ostream_iterator<int> out_it(os, " | ");

// 2. Usage with STL algorithm (std::copy)
std::copy(data.begin(), data.end(), out_it);
// Output: 10 | 20 | 30 | 40 |

// 3. Manual write (behaves like an output iterator)
*out_it = 99;
// Output: 99 |
++out_it; // Increment does nothing, but is required by concept

// Special form: End-of-stream iterator (rarely used for output)
std::ostream_iterator<int> end_it;
// end_it is the default constructed iterator
// Do not attempt to dereference end_it
// or write to it.
